export const preflightCheckSchema = z.object({
  name: z.string(),
  variant: z.string(),
  passed: z.boolean(),
  durationMs: z.string(),
  details: z.string().optional(),
})

export const preflightErrorSchema = z.object({
  code: z.union([
    z.literal('E_PREFLIGHT_TIMEOUT'),
    z.literal('E_PREFLIGHT_FAILED'),
    z.literal('E_PREFLIGHT_PACK_INVISIBLE'),
    z.literal('E_AUTH_MISSING'),
    z.literal('E_PACK_CHECK_FAILED'),
  ]),
  phase: z.literal('preflight'),
  check: z.union([
    z.literal('opencode-launch'),
    z.literal('auth-ping'),
    z.literal('build-agent'),
    z.literal('pack-visibility'),
    z.literal('foreign-pack-absent'),
    z.literal('pack-functional'),
  ]),
  variant: z.string(),
  message: z.string(),
  context: recordUnknownSchema.optional(),
})

export const variantHomesForCheckSchema = z.object({
  name: z.string(),
  homes: z.array(homeCheckTargetSchema),
})

export const preflightInputSchema = z.object({
  runInput: runInputSchema,
  manifest: manifestSchema,
  homesForCheck: z.array(variantHomesForCheckSchema),
})

export const preflightResultSchema = z.object({
  checks: z.array(preflightCheckSchema),
  allPassed: z.boolean(),
  exitCode: z.union([z.literal(0), z.literal(2), z.literal(3)]),
  logPath: z.string(),
})

export const repoCloneErrorSchema = z.object({
  code: z.union([z.literal('E_REPO_TIMEOUT'), z.literal('E_REPO_CLONE_FAILED')]),
  message: z.string(),
  repoUrl: z.string(),
  context: recordUnknownSchema.optional(),
})

export const repoCloneInputSchema = z.object({
  runInput: runInputSchema,
  manifest: manifestSchema,
  workspace: workspaceTreeSchema,
})

export const variantCopyPathsSchema = z.object({
  name: z.string(),
  paths: z.array(z.string()),
})

export const repoCloneResultSchema = z.object({
  sourcePath: z.string(),
  copyPaths: z.array(variantCopyPathsSchema),
  cloneDurationMs: z.string(),
})

export const timelineEventTypeSchema = z.enum([
  'reasoning',
  'tool-call',
  'tool-result',
  'step-finish',
  'text',
])

export const timelineEventSchema = z.object({
  tStart: z.string(),
  tEnd: z.string(),
  variant: z.string(),
  runIndex: z.number().int(),
  sessionId: z.string(),
  parentSessionId: z.string().optional(),
  swimlaneDepth: z.number().int(),
  type: timelineEventTypeSchema,
  tool: z.string().optional(),
  tokens: z.number().int().optional(),
  status: z
    .union([z.literal('pending'), z.literal('running'), z.literal('completed'), z.literal('error')])
    .optional(),
})

export const variantTimelineSchema = z.object({
  variant: z.string(),
  events: z.array(timelineEventSchema),
})

export const timelineSchema = z.object({
  lanes: z.array(variantTimelineSchema),
  mode: timelineModeSchema,
})

export const variantSummarySchema = z.object({
  variant: z.string(),
  improvements: z.array(metricDeltaSchema),
  regressions: z.array(metricDeltaSchema),
  neutral: z.array(metricDeltaSchema),
})

export const reportSummarySchema = z.object({
  headlineResult: z.string(),
  perVariant: z.array(variantSummarySchema),
  failures: z.array(failedRunSchema),
  basis: z.union([z.literal('task'), z.literal('total')]).optional(),
})

export const reportSchema = z.object({
  schemaVersion: schemaVersionSchema,
  manifest: manifestSchema,
  metrics: metricsReportSchema,
  timeline: timelineSchema,
  diffs: z.array(diffResultSchema),
  judge: judgeResultSchema.optional(),
  summary: reportSummarySchema,
  prep: prepReportSchema.optional(),
})

export const reportRenderErrorSchema = z.object({
  code: z.union([z.literal('E_DISK_FULL'), z.literal('E_EXPORT_INVALID')]),
  message: z.string(),
  context: recordUnknownSchema.optional(),
})

export const reportRenderInputSchema = z.object({
  runInput: runInputSchema,
  manifest: manifestSchema,
  metrics: metricsReportSchema,
  timeline: timelineSchema,
  diffs: z.array(diffResultSchema),
  judge: judgeResultSchema.optional(),
  summary: reportSummarySchema,
  prep: prepReportSchema.optional(),
})

export const reportRenderResultSchema = z.object({
  formats: z.array(outputFormatSchema),
  paths: z.object({
    md: z.string().optional(),
    json: z.string().optional(),
    yaml: z.string().optional(),
    html: z.string().optional(),
  }),
  stdoutFormat: z.union([z.literal('md'), z.literal('json')]),
})

export const reviewWorkspaceInputSchema = z.object({
  runInput: runInputSchema,
  manifest: manifestSchema,
  workspace: workspaceTreeSchema,
})

export const reviewWorkspaceResultSchema = z.object({
  workspacePath: z.string(),
  opened: z.boolean(),
  command: z.string(),
})

export const runSideErrorSchema = z.object({
  code: z.union([
    z.literal('E_RUN_TIMEOUT'),
    z.literal('E_RUN_HANG_WATCHDOG'),
    z.literal('E_RUN_CRASH'),
    z.literal('E_VERIFY_TIMEOUT'),
    z.literal('E_VERIFY_FAILED'),
    z.literal('E_RATE_LIMIT_EXHAUSTED'),
    z.literal('E_OOM'),
    z.literal('E_DISK_FULL'),
    z.literal('E_PORT_CONFLICT'),
    z.literal('E_EXPORT_INVALID'),
    z.literal('E_TOTAL_TIMEOUT'),
  ]),
  message: z.string(),
  variant: z.string(),
  runIndex: z.number().int(),
  context: recordUnknownSchema.optional(),
})

export const runSideInputSchema = z.object({
  runInput: runInputSchema,
  manifest: manifestSchema,
  workspace: workspaceTreeSchema,
  homeEnv: envVarSetSchema,
  variant: z.string(),
  runIndex: z.number().int(),
  sessionId: z.string(),
})

export const timelineErrorSchema = z.object({
  code: z.literal('E_EXPORT_INVALID'),
  message: z.string(),
  variant: z.string().optional(),
  runIndex: z.number().int().optional(),
  context: recordUnknownSchema.optional(),
})

export const timelineInputSchema = z.object({
  runInput: runInputSchema,
  manifest: manifestSchema,
  workspace: workspaceTreeSchema,
  results: z.array(variantRunResultsSchema),
})

export const timelineResultSchema = z.object({
  timeline: timelineSchema,
  jsonPath: z.string(),
  htmlPath: z.string().optional(),
})

export const workspaceSetupErrorSchema = z.object({
  code: z.literal('E_HOME_SETUP_FAILED'),
  message: z.string(),
  reason: z
    .union([
      z.literal('already-exists'),
      z.literal('not-a-directory'),
      z.literal('mkdir-failed'),
      z.literal('write-failed'),
    ])
    .optional(),
  path: z.string().optional(),
  context: recordUnknownSchema.optional(),
})

export const workspaceSetupInputSchema = z.object({
  runInput: runInputSchema,
  runId: z.string(),
})

export const workspaceSetupResultSchema = z.object({
  manifest: manifestSchema,
  rootPath: z.string(),
  treePaths: workspaceTreeSchema,
})
